53 |     pub fn concat(buffers: &[Self]) -> Self {
54 |         let total_len = buffers.iter().map(|b| b.len()).sum();
55 |         let mut data = Vec::with_capacity(total_len);
56 |         for buffer in buffers {
57 |             data.extend_from_slice(buffer.as_ref());
